    if not isinstance(sensor_str, str):
        return output

    parts = sensor_str.split('|')
    for part in parts:
        if ':' not in part:
            continue
        key, value = part.split(':', 1)
        if key in key_map:
            dict_key = key_map[key]
            if dict_key == 'timestamp':
                try:
                    output[dict_key] = int(value)
                except:
                    output[dict_key] = None
            else:
                try:
                    output[dict_key] = float(value)
                except:
                    output[dict_key] = None
    return output

